  for (let k = 0; k < 4; k++) p.box(0.006, 0.18, 0.006, -0.045 + k * 0.03, 0.12, 0.897, 0x4a4a4e);
  for (let k = 0; k < 4; k++) p.box(0.12, 0.006, 0.006, 0, 0.14 + k * 0.035, 0.897, 0x4a4a4e);
