  for (const s of [-1, 1]) p.add(new THREE.BoxGeometry(0.004, 0.004, 0.3), s * 0.06, 0.2, 0.96, 0x3c3c40, 0, false, 0, -0.55);
  // le donjon carré, ses meurtrières, ses créneaux, son échauguette, sa bannière
