    caveSeated(p, -0.08, -0.38, 0, 0, 0.01); caveSeated(p, 0.08, -0.38, -0.2, 2, 0.01);
    caveSeated(p, -0.34, 0.17, 2.03, 1, 0.01); caveSeated(p, 0.36, 0.2, -2.03, 4, 0.01);
    caveFolk(p, 0.02, 0.42, Math.PI, 3, 'cheer');
