    p.add(new THREE.CylinderGeometry(0.004, 0.004, 0.38, 4).rotateZ(Math.PI / 2), 0, 0.2, 0.02, C.wood);
    p.add(new THREE.IcosahedronGeometry(0.035, 0).scale(1.5, 0.8, 0.9), 0, 0.2, 0.02, 0x8a3a26);
