    p.box(0.94, 0.004, 0.13, 0, 0.008, 0, gravel); p.box(0.13, 0.004, 0.94, 0, 0.008, 0, gravel);
    p.cyl(0.235, 0.235, 0.004, 16, 0, 0.008, 0, gravel);
