    fountainFr(p, 0, 0, 0.15, 0.012);
    const fl = [[0xd84a5a, 0xf2d25a], [0xb48ae0, 0xf4f2ee], [0xf28a5e, 0xd84a5a], [0xf2d25a, 0x8a6ad8]];
    let k = 0;
