    p.cyl(0.045, 0.045, 0.07, 8, 0, 1.0, -0.66, stone); for (let i = 0; i < 6; i++) { const a = (i / 6) * Math.PI * 2; p.box(0.01, 0.05, 0.004, Math.cos(a) * 0.046, 1.01, -0.66 + Math.sin(a) * 0.046, glassC, -a + Math.PI / 2, true); }
