      for (let k = 0; k < 9; k++) p.box(0.014, 0.04, 0.014, x0 - 0.17 + k * 0.0425, 0.53, -0.1, C.white);
      p.box(0.38, 0.012, 0.02, x0, 0.57, -0.1, C.white);
