    l.box(0.07, 0.008, 0.07, 0, -0.078, 0, iron);
    for (const [u, w] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) l.box(0.007, 0.09, 0.007, u * 0.032, -0.168, w * 0.032, iron);
    l.box(0.058, 0.08, 0.058, 0, -0.163, 0, 0xffd890, 0, true);
