    for (const z of [0.4, 0.62]) p.add(new THREE.CylinderGeometry(0.03, 0.03, 0.17, 8).rotateZ(Math.PI / 2), -0.3, 0.04, z, 0x3c3c40);
    p.box(0.06, 0.012, 0.006, -0.32, 0.18, 0.67, 0x3a7aff, 0, true);
