  p.box(0.12, 0.012, 0.012, TX - 0.02, TY + 0.36, TZ, 0x9aa3ad); p.cyl(0.004, 0.004, 0.1, 4, TX + 0.04, TY + 0.225, TZ + 0.06, 0x9aa3ad);
