  for (let i = 0; i < 4; i++) pb(0.3, 0.014, 0.03, X, zs + 0.3 + i * 0.28, hy0 + H * 0.78, wood);
  pb(0.3, 0.012, 0.3, X, zs + 0.2, hy0 + H * 0.78 + 0.07, wood);
