  const hook = (x: number, y: number, z: number, c: number) => { p.box(0.005, 0.04, 0.005, x, y - 0.04, z, 0x6a727c); p.box(0.016, 0.005, 0.005, x + 0.006, y - 0.042, z, 0x6a727c); fish(x, y - 0.075, z, c, Math.PI / 2 + 0.2, 0.9); };
