  for (const [x, y, z] of [[0.3, 0, -0.78], [0.3, 0.07, -0.78], [0.18, 0, -0.78]]) crate(x, g + y, z, 0.05);
  for (let k = 0; k < 3; k++) p.box(0.09, 0.07, 0.08, 0.38, g + k * 0.07, -0.55, 0xdceaf4, 0.12 * k);
