  p.box(0.06, 0.008, 0.04, 0.1, g, -0.42, C.darkwood);
  const bal = swing([0.1, g + 0.25, -0.42], [0, 0, 1], 0.1, 0.3);
  bal.box(0.26, 0.01, 0.01, 0, -0.005, 0, old ? C.darkwood : 0x6a727c);
  bal.box(0.01, 0.025, 0.01, 0, 0.005, 0, 0x6a727c);
