    seated(p, -0.26, 0.062, 0.43, Math.PI, 0x3a6ab8); seated(p, -0.18, 0.062, 0.43, Math.PI, 0xf2a6c8, 0x8a5a3a); seated(p, 0.26, 0.062, 0.43, Math.PI, 0x4fa860, 0x2a2420);
