    for (const x of [-0.15, -0.05, 0.05, 0.15]) p.add(new THREE.ConeGeometry(0.02, 0.06, 4).rotateX(Math.PI / 2), x, 0.07, 0.22, bronze);
    actor(p, 0, 0.12, 0.1, 0, 0xf2ead8);
