    waterPool(p, 0.22, 0.072, -0.14, 0.08, 12); p.cyl(0.012, 0.018, 0.1, 6, 0.22, 0.02, -0.14, marble); waterJet(p, 0.22, 0.12, -0.14, 0.06);
    // colonne triomphale à frise en spirale, sa statue
