  p.box(0.06, 0.006, 0.34, -0.86, 0.026, cz + 0.05, modern ? 0xc85a44 : 0xb88a6a); p.box(0.1, 0.01, 0.16, -0.86, 0.026, cz - 0.2, 0xe8d8a8);
