  for (const d of [-0.115, 0.115]) { p.box(2.8, 0.012, 0.012, 0.05, y0 + rh + 0.12, rz + d, iron); for (let x = -1.3; x <= 1.4; x += 0.28) p.box(0.012, 0.1, 0.012, x, y0 + rh + 0.034, rz + d, iron); }
