  const wx = 1.1, wz = -0.42, wh = 1.3, half = (t: number) => 0.16 - 0.125 * t;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) pipe(p, [wx + sx * 0.16, y0, wz + sz * 0.16], [wx + sx * 0.035, y0 + wh, wz + sz * 0.035], 0.012, 0x6a4a30);
