  for (const [x, z] of [[-0.32, -0.98], [0.3, -1.38]]) for (let k = 0; k < 3; k++) p.cone(0.012, 0.1, 4, x + k * 0.03, F, z, 0x5f8040);
  // le panneau d'information : un crocodile peint
