  p.add(new THREE.SphereGeometry(0.1, 7, 4, 0, Math.PI * 2, 0, Math.PI / 2).scale(1, 0.8, 0.9), -1.12, F, -0.36, rockB, 0.1);
  p.box(0.07, 0.07, 0.03, -1.22, F, -0.24, 0x2a2622, 0.3);
