  floor(0.52, -0.52, 1.44, 0.24, 0xb8c68a);
  pen(0.52, -0.52, 1.44, 0.24, 0.76, 0x7a6355, false, 0.1);
  pond(0.8, -0.14, 0.17);
  rock(0.62, -0.38, 0.05); rock(0.98, 0.0, 0.05, rockB);
